// Auth Header Parser
pub fn parse_bearer_token(auth_header: Option<&str>) -> Result<String, String> {
    let header = auth_header.ok_or("Missing header")?;
    if let Some(token) = header.strip_prefix("Bearer ") {
        Ok(token.to_string())
    } else {
        Err("Invalid bearer prefix".to_string())
    }
}

